            <DialogActions sx={{ borderTop: '1px solid', borderColor: 'divider', justifyContent: 'flex-end' }}>
                <Button onClick={handleCancel} variant="outlined">Cancel</Button>
                <PrimaryChangesConfirmButton onConfirm={handleConfirm} />
            </DialogActions>
        </Dialog>
    );
}

